CREATE OR REPLACE FUNCTION private.agreement_calendar_interval(p_terms jsonb)
 RETURNS TABLE(starts_at timestamp with time zone, ends_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  s text := p_terms->>'proposed_start_at';
  e text := p_terms->>'proposed_end_at';
  pattern text := '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,6})?(Z|[+-](0[0-9]|1[0-5]):[0-5][0-9])$';
begin
  if jsonb_typeof(p_terms) is distinct from 'object' then
    raise exception 'AGREEMENT_CALENDAR_INTERVAL_INVALID' using errcode='22023';
  end if;
  if s is null and e is null then
    return query select null::timestamptz,null::timestamptz;
    return;
  end if;
  if s is null or e is null or jsonb_typeof(p_terms->'proposed_start_at') <> 'string'
     or jsonb_typeof(p_terms->'proposed_end_at') <> 'string'
     or length(s)>32 or length(e)>32 or s !~ pattern or e !~ pattern then
    raise exception 'AGREEMENT_CALENDAR_INTERVAL_INVALID' using errcode='22023';
  end if;
  begin
    starts_at := s::timestamptz;
    ends_at := e::timestamptz;
  exception when datetime_field_overflow or invalid_datetime_format or invalid_parameter_value then
    raise exception 'AGREEMENT_CALENDAR_INTERVAL_INVALID' using errcode='22023';
  end;
  if not isfinite(starts_at) or not isfinite(ends_at) or starts_at>=ends_at then
    raise exception 'AGREEMENT_CALENDAR_INTERVAL_INVALID' using errcode='22023';
  end if;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_worker_calendar_event(p_agreement_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  a public.agreements%rowtype;
  terms jsonb;
  interval_start timestamptz;
  interval_end timestamptz;
begin
  select ag.* into a from public.agreements ag where ag.id=p_agreement_id;
  if not found then return; end if; -- deletion cascades its projection
  select av.terms into terms from public.agreement_versions av
    where av.agreement_id=a.id and av.version=a.current_version;
  if not found then raise exception 'AGREEMENT_CALENDAR_VERSION_MISSING' using errcode='P0001'; end if;
  if not exists(select 1 from public.app_profiles p where p.id=a.worker_profile_id
    and p.account_id=a.worker_account_id and p.kind='WORKER') then
    raise exception 'AGREEMENT_CALENDAR_WORKER_MISMATCH' using errcode='P0001';
  end if;

  -- Always serialize acquisition, movement, cancellation and completion.
  -- The subsequent query gets a fresh READ COMMITTED snapshot; a stale higher
  -- isolation transaction must abort on the fence update, not double-book.
  insert into private.worker_calendar_serialization(worker_profile_id) values(a.worker_profile_id)
    on conflict(worker_profile_id) do update set touched_at=statement_timestamp();
  if a.status<>'CONFIRMED' then
    update private.worker_calendar_events set state='RELEASED',agreement_status=a.status,
      agreement_version=a.current_version,updated_at=statement_timestamp() where agreement_id=a.id;
    return;
  end if;

  select i.starts_at,i.ends_at into interval_start,interval_end
    from private.agreement_calendar_interval(terms) i;
  if interval_start is null then
    delete from private.worker_calendar_events where agreement_id=a.id;
    return;
  end if;
  -- A price/scope-only version must not invalidate legitimate grandfathered
  -- overlap. Only an unchanged existing interval qualifies for this exception.
  if not exists(select 1 from private.worker_calendar_events e where e.agreement_id=a.id
      and e.worker_profile_id=a.worker_profile_id and e.worker_account_id=a.worker_account_id
      and e.state='BLOCKING' and e.starts_at=interval_start and e.ends_at=interval_end)
     and private.worker_calendar_conflict(a.worker_profile_id,interval_start,interval_end,a.id) then
    raise exception 'WORKER_CALENDAR_CONFLICT' using errcode='P0001',detail='CALENDAR_CONFLICT';
  end if;
  insert into private.worker_calendar_events(agreement_id,worker_account_id,worker_profile_id,
    agreement_version,starts_at,ends_at,state,agreement_status)
  values(a.id,a.worker_account_id,a.worker_profile_id,a.current_version,interval_start,interval_end,'BLOCKING',a.status)
  on conflict(agreement_id) do update set worker_account_id=excluded.worker_account_id,
    worker_profile_id=excluded.worker_profile_id,agreement_version=excluded.agreement_version,
    starts_at=excluded.starts_at,ends_at=excluded.ends_at,state=excluded.state,
    agreement_status=excluded.agreement_status,updated_at=statement_timestamp();
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_need_completion(p_need_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  n public.needs;
  v_completed_slots integer := 0;
  v_active_selected_slots integer := 0;
  v_effective_required integer := 0;
begin
  select * into n
    from public.needs
   where id = p_need_id
   for update;

  if not found then
    return false;
  end if;

  if n.status = 'COMPLETED' then
    return true;
  end if;

  if n.status not in ('ACTIVE','SELECTION') then
    return false;
  end if;

  select coalesce(sum(s.covered_slots), 0)::integer
    into v_completed_slots
    from public.need_selections s
    join public.agreements a on a.selection_id = s.id
   where s.need_id = p_need_id
     and s.status = 'SELECTED'
     and a.status = 'COMPLETED';

  -- When remaining search was explicitly closed, evaluate against active selected slots
  if n.remaining_search_closed_at is not null then
    select coalesce(sum(s.covered_slots), 0)::integer
      into v_active_selected_slots
      from public.need_selections s
     where s.need_id = p_need_id
       and s.status = 'SELECTED';
    v_effective_required := v_active_selected_slots;
  else
    v_effective_required := n.required_slots;
  end if;

  if v_effective_required < 1 or v_completed_slots < v_effective_required then
    return false;
  end if;

  perform set_config('uskoci.need_lifecycle', 'COMPLETE', true);

  update public.needs
     set status = 'COMPLETED',
         updated_at = statement_timestamp()
   where id = p_need_id
     and status in ('ACTIVE','SELECTION');

  return found;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_agreement_cancellation_v1(p_agreement_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_items jsonb;
begin
  -- CANCEL-INFO (2026-10-07): "Otkazano {datum} - {ko} - {razlog}" for the Dogovori list and detail, for the CALLER's own
  -- Dogovori only. The reason is the canceller's own message in the Dogovor's conversation, which both parties already read there
  -- (the chat readers show it whatever a later block says), so this discloses nothing beyond the Dogovor. An id that is not the
  -- caller's Dogovor, or does not exist, is simply left out (no error that would reveal it). Up to 100 ids per call, in the order
  -- given, each once.
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  if private.closure_account_restricted(v_uid) then raise exception 'ACCOUNT_CLOSING' using errcode = '42501'; end if;
  if p_agreement_ids is null or cardinality(p_agreement_ids) not between 1 and 100 or array_ndims(p_agreement_ids) <> 1
     or array_position(p_agreement_ids, null) is not null then
    raise exception 'INVALID_AGREEMENT_IDS' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(x.item order by x.ord), '[]'::jsonb) into v_items
  from (
    select ids.ord, jsonb_build_object(
        'agreementId', a.id,
        'cancelled', a.status = 'CANCELLED',
        'cancelledAt', f.facts->'cancelledAt',
        'cancelledBy', f.facts->'cancelledBy',
        'cancelledByMe', case when f.facts->>'cancelledByAccountId' is null then null
                              else (f.facts->>'cancelledByAccountId')::uuid = v_uid end,
        'reason', f.facts->'reason',
        'reasonState', f.facts->'reasonState') as item
      from (select u.id, min(u.ord) as ord from unnest(p_agreement_ids) with ordinality u(id, ord) group by u.id) ids
      join public.agreements a on a.id = ids.id and v_uid in (a.requester_account_id, a.worker_account_id)
      left join lateral (select private.agreement_cancellation_facts_v1(a.id) as facts) f on a.status = 'CANCELLED'
  ) x;
  return jsonb_build_object('schema', 'AGREEMENT_CANCELLATION_V1', 'items', v_items, 'asOf', statement_timestamp(), 'authoritative', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_confirm_completion(p_agreement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  uid uuid:=auth.uid();
  v_need_id uuid;
  n public.needs%rowtype;
  a public.agreements%rowtype;
  x public.agreement_execution%rowtype;
  v_completed_at timestamptz;
  need_completed boolean;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;

  select ag.need_id into v_need_id from public.agreements ag where ag.id=p_agreement_id;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;

  select * into n from public.needs nd where nd.id=v_need_id for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;

  select * into a from public.agreements ag where ag.id=p_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;
  if a.need_id<>n.id then raise exception 'AGREEMENT_NEED_MISMATCH' using errcode='P0001'; end if;
  if a.requester_account_id<>uid then
    raise exception 'ONLY_REQUESTER_CAN_CONFIRM_COMPLETION' using errcode='42501';
  end if;

  select * into x from public.agreement_execution ex where ex.agreement_id=a.id for update;
  if not found then raise exception 'EXECUTION_NOT_FOUND' using errcode='P0002'; end if;
  if x.agreement_version<>a.current_version then
    raise exception 'EXECUTION_VERSION_MISMATCH' using errcode='P0001';
  end if;

  if a.status='COMPLETED' and x.state='COMPLETED' then
    return jsonb_build_object(
      'agreementId',a.id,'state','COMPLETED',
      'completedAt',x.completed_at,
      'idempotentReplay',true,'authoritative',true
    );
  end if;

  if a.status='CANCELLED' or x.state='CANCELLED' then
    raise exception 'AGREEMENT_CANCELLED' using errcode='P0001';
  end if;

  if a.status<>'CONFIRMED'
     or x.state not in ('CONFIRMED','AWAITING_REQUESTER') then
    raise exception 'COMPLETION_NOT_CONFIRMABLE'
      using errcode='P0001',
            detail=jsonb_build_object('agreementStatus',a.status,'executionState',x.state)::text;
  end if;

  if exists(select 1 from public.agreement_change_proposals where agreement_id=a.id and status='PENDING') then
    raise exception 'AGREEMENT_CHANGE_PENDING' using errcode='P0001';
  end if;

  v_completed_at:=statement_timestamp();

  update public.agreement_execution ex
     set state='COMPLETED',
         completed_at=coalesce(ex.completed_at,v_completed_at),
         requester_deadline_at=null,
         updated_at=statement_timestamp()
   where ex.agreement_id=a.id
  returning ex.* into x;

  update public.agreements ag
     set status='COMPLETED',updated_at=statement_timestamp()
   where ag.id=a.id;

  need_completed:=private.sync_need_completion(n.id);

  perform private.emit_event(
    a.worker_account_id,'WORKER','EXECUTION_STATE_CHANGED',
    'AGREEMENT',a.id,a.current_version,
    'Dogovor je završen',
    'Naručilac je potvrdio završetak.',
    'completed:worker:'||a.id::text||':'||a.current_version::text,
    'NORMAL',
    jsonb_build_object('completedAt',x.completed_at),
    null
  );

  return jsonb_build_object(
    'agreementId',a.id,
    'state','COMPLETED',
    'completedAt',x.completed_at,
    'needCompleted',need_completed,
    'problemWasPreviouslyReported',x.problem_opened_at is not null,
    'idempotentReplay',false,
    'authoritative',true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_mark_work_done(p_agreement_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  uid uuid:=auth.uid();
  v_need_id uuid;
  n public.needs%rowtype;
  a public.agreements%rowtype;
  x public.agreement_execution%rowtype;
  deadline timestamptz;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;

  select ag.need_id into v_need_id from public.agreements ag where ag.id=p_agreement_id;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;

  select * into n from public.needs nd where nd.id=v_need_id for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;

  select * into a from public.agreements ag where ag.id=p_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;
  if a.need_id<>n.id then raise exception 'AGREEMENT_NEED_MISMATCH' using errcode='P0001'; end if;
  if a.worker_account_id<>uid then raise exception 'ONLY_WORKER_CAN_MARK_DONE' using errcode='42501'; end if;

  select * into x from public.agreement_execution ex where ex.agreement_id=a.id for update;
  if not found then raise exception 'EXECUTION_NOT_FOUND' using errcode='P0002'; end if;
  if x.agreement_version<>a.current_version then
    raise exception 'EXECUTION_VERSION_MISMATCH' using errcode='P0001';
  end if;

  if a.status='CANCELLED' or x.state='CANCELLED' then
    raise exception 'AGREEMENT_CANCELLED' using errcode='P0001';
  end if;
  if a.status='COMPLETED' or x.state='COMPLETED' then
    raise exception 'AGREEMENT_ALREADY_COMPLETED' using errcode='P0001';
  end if;
  if a.status<>'CONFIRMED' then
    raise exception 'AGREEMENT_NOT_ACTIVE' using errcode='P0001',detail=a.status;
  end if;

  if x.state='AWAITING_REQUESTER' then
    if x.requester_deadline_at is null or x.worker_marked_done_at is null then
      raise exception 'COMPLETION_STATE_CORRUPT' using errcode='P0001';
    end if;
    return x.requester_deadline_at; -- exact replay, no UPDATE, no new event
  end if;

  if x.state<>'CONFIRMED' then
    raise exception 'EXECUTION_NOT_MARKABLE_DONE' using errcode='P0001',detail=x.state;
  end if;

  if exists(select 1 from public.agreement_change_proposals where agreement_id=a.id and status='PENDING') then
    raise exception 'AGREEMENT_CHANGE_PENDING' using errcode='P0001';
  end if;

  deadline:=statement_timestamp()+interval '48 hours';

  update public.agreement_execution ex
     set state='AWAITING_REQUESTER',
         worker_marked_done_at=statement_timestamp(),
         requester_deadline_at=deadline,
         updated_at=statement_timestamp()
   where ex.agreement_id=a.id
     and ex.state='CONFIRMED'
  returning ex.* into x;

  if not found then
    raise exception 'COMPLETION_TRANSITION_RACE' using errcode='P0001';
  end if;

  perform private.emit_event(
    a.requester_account_id,'REQUESTER','COMPLETION_REQUIRED',
    'AGREEMENT',a.id,a.current_version,
    'Završetak čeka Vašu potvrdu',
    'Uskočer je označio Dogovor kao završen.',
    'completion-required:'||a.id::text||':'||a.current_version::text,
    'NORMAL',
    jsonb_build_object('requesterDeadlineAt',deadline),
    deadline
  );

  return deadline;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_report_problem(p_agreement_id uuid, p_narrative text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  uid uuid:=auth.uid();
  v_need_id uuid;
  n public.needs%rowtype;
  a public.agreements%rowtype;
  x public.agreement_execution%rowtype;
  narrative text:=nullif(btrim(p_narrative),'');
  first_report boolean;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if narrative is null then raise exception 'NARRATIVE_REQUIRED' using errcode='22023'; end if;
  if length(narrative)>4000 then raise exception 'NARRATIVE_TOO_LONG' using errcode='22023'; end if;

  select ag.need_id into v_need_id from public.agreements ag where ag.id=p_agreement_id;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;

  select * into n from public.needs nd where nd.id=v_need_id for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;

  select * into a from public.agreements ag where ag.id=p_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;
  if uid<>a.requester_account_id and uid<>a.worker_account_id then
    raise exception 'NOT_PARTY' using errcode='42501';
  end if;
  if a.status<>'CONFIRMED' then
    raise exception 'AGREEMENT_NOT_REPORTABLE' using errcode='P0001',detail=a.status;
  end if;

  select * into x from public.agreement_execution ex where ex.agreement_id=a.id for update;
  if not found then raise exception 'EXECUTION_NOT_FOUND' using errcode='P0002'; end if;
  if x.state not in ('CONFIRMED','AWAITING_REQUESTER') then
    raise exception 'EXECUTION_NOT_REPORTABLE' using errcode='P0001',detail=x.state;
  end if;

  first_report:=x.problem_opened_at is null;

  update public.agreement_execution ex
     set problem_opened_at=coalesce(ex.problem_opened_at,statement_timestamp()),
         problem_narrative=coalesce(ex.problem_narrative,narrative),
         problem_opened_by=coalesce(ex.problem_opened_by,uid),
         updated_at=statement_timestamp()
   where ex.agreement_id=a.id
  returning ex.* into x;

  if first_report then
    if not private.safety_pair_blocked(a.requester_account_id,a.worker_account_id)
     and not private.closure_account_restricted(a.requester_account_id) and not private.closure_account_restricted(a.worker_account_id) then
    insert into public.agreement_messages(agreement_id,agreement_version,sender_account_id,body)
    values (a.id,a.current_version,uid,'⚠️ Prijavljen problem: '||narrative);
    end if;

    perform private.emit_event(
      case when uid=a.requester_account_id then a.worker_account_id else a.requester_account_id end,
      case when uid=a.requester_account_id then 'WORKER' else 'REQUESTER' end,
      'RECOVERY_OPENED',
      'AGREEMENT',a.id,a.current_version,
      'Prijavljen je problem',
      'Otvorite Dogovor da vidite prijavljeni problem.',
      'problem:'||a.id::text||':'||a.current_version::text,
      'NORMAL',
      jsonb_build_object('reportedByRole',
        case when uid=a.requester_account_id then 'REQUESTER' else 'WORKER' end),
      null
    );
  end if;

  return jsonb_build_object(
    'agreementId',a.id,
    'problemOpenedAt',x.problem_opened_at,
    'problemOpenedBy',x.problem_opened_by,
    'idempotentReplay',not first_report,
    'noAutomaticFaultOrDebt',true,
    'authoritative',true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_tick_auto_completion()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare candidate record; a public.agreements; x public.agreement_execution; done integer:=0; at_time timestamptz:=statement_timestamp();
begin
 for candidate in select ag.id,ag.need_id from public.agreements ag join public.agreement_execution ex on ex.agreement_id=ag.id
   where ag.status='CONFIRMED' and ex.state='AWAITING_REQUESTER' and ex.problem_opened_at is null
     and ex.requester_deadline_at is not null and ex.requester_deadline_at<=at_time
   order by ag.need_id,ag.id limit 100
 loop
   perform 1 from public.needs where id=candidate.need_id for update skip locked;
   if not found then continue; end if;
   select * into a from public.agreements where id=candidate.id for update skip locked;
   if not found or a.status<>'CONFIRMED' then continue; end if;
   select * into x from public.agreement_execution where agreement_id=a.id for update skip locked;
   if not found or x.state<>'AWAITING_REQUESTER' or x.agreement_version<>a.current_version
     or x.problem_opened_at is not null or x.requester_deadline_at is null or x.requester_deadline_at>at_time
     or exists(select 1 from public.agreement_change_proposals where agreement_id=a.id and status='PENDING') then continue; end if;
   update public.agreement_execution set state='COMPLETED',completed_at=at_time,requester_deadline_at=null,updated_at=at_time where agreement_id=a.id;
   update public.agreements set status='COMPLETED',updated_at=at_time where id=a.id;
   perform private.sync_need_completion(a.need_id);
   -- PKG-029a (deep read 1.2): the worker is told the job closed, exactly as when the requester confirms (same
   -- event, same dedupe key, so the two paths can never both notify).
   perform private.emit_event(a.worker_account_id, 'WORKER', 'EXECUTION_STATE_CHANGED', 'AGREEMENT', a.id, a.current_version,
     'Dogovor je završen', 'Rok za potvrdu je istekao, pa je završetak potvrđen automatski.',
     'completed:worker:' || a.id::text || ':' || a.current_version::text, 'NORMAL',
     jsonb_build_object('completedAt', at_time, 'automatic', true), null);
   done:=done+1;
 end loop;
 return done;
end;
$function$

CREATE OR REPLACE FUNCTION private.closure_guard_owned_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r jsonb; prior jsonb; a uuid; b uuid;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

 r:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 prior:=case when tg_op='INSERT' then '{}'::jsonb else to_jsonb(old) end;
 if tg_table_name='needs' and tg_op='UPDATE' and (r->>'status') is distinct from (prior->>'status') and (r->>'status') in('CANCELLED','COMPLETED','EXPIRED','ARCHIVED') then return new; end if;
 if tg_table_name='marketplace_responses' and tg_op='UPDATE' and (r->>'status') is distinct from (prior->>'status') and (r->>'status') in('WITHDRAWN','EXPIRED','NOT_SELECTED','STALE') then return new; end if;
 if tg_table_name='agreements' and tg_op='UPDATE' and (r->>'status') is distinct from (prior->>'status') and (r->>'status') in('CANCELLED','COMPLETED') then return new; end if;
 if tg_table_name='agreement_versions' and tg_op='UPDATE' and (r->>'status')='CANCELLED' then return new; end if;
 if tg_table_name='agreement_change_proposals' and tg_op='UPDATE' and (r->>'status') not in('PENDING','ACCEPTED') then return new; end if;
 if tg_table_name='access_grants' and tg_op='UPDATE' and (r->>'status')='REVOKED' then return new; end if;
 if tg_table_name='notification_push_devices' and tg_op='UPDATE' and (r->>'active')::boolean is false
  and (r->>'user_id')=(prior->>'user_id') and (r->>'expo_push_token')=(prior->>'expo_push_token') and (r->>'platform')=(prior->>'platform') then return new; end if;
 if tg_table_name='ai_need_turn_commands' and tg_op='UPDATE' and (prior->>'state')='PROCESSING' and (r->>'state') in('SUCCEEDED','FAILED') then return new; end if;
 -- Export remains a separate request/read/cancel capability; only a new
 -- processing claim is fenced. Existing attempts can settle without new work.
 if tg_table_name='data_export_requests' and (r->>'status')<>'PROCESSING' then
  if tg_op='DELETE' then return old; end if; return new;
 end if;
 if tg_table_name='retention_jobs' and (r->>'status')<>'CLAIMED' then return new; end if;
 if tg_argv[0]='ACCOUNT' then a:=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='PROFILE' then select account_id into a from public.app_profiles where id=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='NEED' then select requester_account_id into a from public.needs where id=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='CONVERSATION' then select account_id into a from public.ai_conversations where id=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='PAIR' then a:=(r->>tg_argv[1])::uuid;b:=(r->>tg_argv[2])::uuid;
 elsif tg_argv[0]='AGREEMENT' then select requester_account_id,worker_account_id into a,b from public.agreements where id=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='RESPONSE' then select n.requester_account_id,m.worker_account_id into a,b from public.marketplace_responses m join public.needs n on n.id=m.need_id where m.id=(r->>tg_argv[1])::uuid;
 elsif tg_argv[0]='APPLICATION' then select requester_account_id into a from public.needs where id=(r->>'need_id')::uuid;b:=(r->>'worker_account_id')::uuid;
 else raise exception 'CLOSURE_CONTEXT_INVALID' using errcode='42501'; end if;
 perform private.closure_assert_open(a,b);
 if tg_op='DELETE' then return old; end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.emit_event(p_recipient uuid, p_role text, p_event_type text, p_entity_type text, p_entity_id uuid, p_entity_version integer, p_title text, p_body text, p_dedupe_key text, p_urgency text DEFAULT 'NORMAL'::text, p_payload jsonb DEFAULT '{}'::jsonb, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_event_id uuid;
  v_prefs public.notification_preferences%rowtype;
  v_cat text := private.category_of_event(p_event_type);
  v_cat_on boolean;
  v_quiet boolean;
  v_prio text := case when p_urgency = 'HITNO' then 'HIGH' else 'NORMAL' end;
  v_suppress text;
begin
  p_title := private.notification_copy_v5(p_title);
  p_body := private.notification_copy_v5(p_body);
  -- 1) durable event, idempotentno
  insert into public.user_activity_events
    (recipient_user_id, recipient_role, event_type, entity_type, entity_id,
     entity_version, urgency, payload, dedupe_key)
  values (p_recipient, p_role, p_event_type, p_entity_type, p_entity_id,
     p_entity_version, p_urgency, p_payload, p_dedupe_key)
  on conflict (dedupe_key) do nothing
  returning id into v_event_id;

  if v_event_id is null then
    return null;  -- vec emitovano; nista se ne duplira
  end if;

  -- 2) preference; ako red ne postoji, vaze podrazumevane vrednosti (push ukljucen za nove korisnike)
  select * into v_prefs from public.notification_preferences
   where user_id = p_recipient and role_context = p_role;
  if not found then
    v_prefs.in_app_enabled := true;
    v_prefs.push_enabled := coalesce((select np.push_enabled from public.notification_preferences np
                                       where np.user_id = p_recipient order by np.role_context limit 1), true);
    v_prefs.quiet_hours_enabled := false;
    v_prefs.urgent_overrides_quiet_hours := false;
    v_prefs.opportunities_enabled := true; v_prefs.responses_enabled := true;
    v_prefs.dogovor_enabled := true; v_prefs.execution_enabled := true;
    v_prefs.recovery_enabled := true; v_prefs.account_enabled := true;
  end if;

  v_cat_on := case v_cat
    when 'opportunities' then v_prefs.opportunities_enabled
    when 'responses'     then v_prefs.responses_enabled
    when 'dogovor'       then v_prefs.dogovor_enabled
    when 'execution'     then v_prefs.execution_enabled
    when 'recovery'      then v_prefs.recovery_enabled
    else v_prefs.account_enabled end;

  -- 3) IN_APP
  insert into public.notification_deliveries
    (event_id, recipient_user_id, recipient_role, channel, priority, state,
     suppression_reason, title, body, dedupe_key, expires_at)
  values (v_event_id, p_recipient, p_role, 'IN_APP', v_prio,
     case when v_prefs.in_app_enabled and v_cat_on then 'CREATED' else 'SUPPRESSED' end,
     case when v_prefs.in_app_enabled and v_cat_on then null
          when not v_cat_on then 'CATEGORY_OFF' else 'IN_APP_OFF' end,
     p_title, p_body, p_dedupe_key || ':in_app', p_expires_at)
  on conflict (dedupe_key) do nothing;

  -- 4) PUSH — tihi sati se postuju osim uz izricit opt-in za HITNO
  v_quiet := private.in_quiet_hours(v_prefs);
  v_suppress := case
    when not v_prefs.push_enabled then 'PUSH_OFF'
    when not v_cat_on then 'CATEGORY_OFF'
    when v_quiet and not (p_urgency = 'HITNO' and v_prefs.urgent_overrides_quiet_hours)
      then 'QUIET_HOURS'
    else null end;

  insert into public.notification_deliveries
    (event_id, recipient_user_id, recipient_role, channel, priority, state,
     suppression_reason, title, body, dedupe_key, expires_at)
  values (v_event_id, p_recipient, p_role, 'PUSH', v_prio,
     case when v_suppress is null then 'CREATED' else 'SUPPRESSED' end,
     v_suppress, p_title, p_body, p_dedupe_key || ':push', p_expires_at)
  on conflict (dedupe_key) do nothing;

  return v_event_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_closed_remaining_search_response()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_closed timestamptz;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if new.status not in ('DRAFT','SUBMITTED','DELIVERED','VIEWED','SHORTLISTED','SELECTED') then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and new.status is not distinct from old.status
     and new.submitted_against_need_revision is not distinct from old.submitted_against_need_revision
     and new.current_version is not distinct from old.current_version then
    return new;
  end if;

  select n.remaining_search_closed_at into v_closed
    from public.needs n
   where n.id = new.need_id;

  if v_closed is not null then
    raise exception 'NEED_REMAINING_SEARCH_CLOSED' using errcode='P0001';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_need_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  token text := current_setting('uskoci.need_lifecycle', true);
  material boolean;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if (tg_op='INSERT' and (new.task_country_code is not null or new.task_timezone is not null))
    or (tg_op='UPDATE' and (new.task_country_code is distinct from old.task_country_code or new.task_timezone is distinct from old.task_timezone)) then
    if current_setting('uskoci.need_region',true) is distinct from 'CONFIRMED_REVIEW' then
      raise exception 'NEED_COUNTRY_REQUIRES_CONFIRMED_REVIEW' using errcode='42501';
    end if;
    perform private.require_location_country(to_jsonb(new.task_country_code));
    if new.task_timezone is distinct from (select default_timezone from private.location_market_configs where country_code=new.task_country_code) then
      raise exception 'NEED_COUNTRY_TIMEZONE_MISMATCH' using errcode='22023';
    end if;
  end if;
  if not exists (
    select 1 from public.app_profiles p
     where p.id = new.requester_profile_id
       and p.account_id = new.requester_account_id
       and p.kind = 'REQUESTER'
  ) then
    raise exception using errcode='42501', message='PROFILE_NOT_OWNED_BY_ACCOUNT';
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'DRAFT'
       and not (new.status = 'PUBLISHED' and token = 'PUBLISH') then
      raise exception using errcode='22023', message='NEED_MUST_START_AS_DRAFT';
    end if;
    if token is null then
      new.urgent := false;
      new.urgent_activated_at := null;
      new.urgent_expires_at := null;
      new.urgent_policy_version := null;
      new.published_at := null;
      new.response_deadline := null;
    end if;
    return new;
  end if;

  if old.status in ('COMPLETED','CANCELLED','EXPIRED','ARCHIVED')
     and (
       (to_jsonb(new) - array['urgent','updated_at'])
         is distinct from
       (to_jsonb(old) - array['urgent','updated_at'])
       or (not coalesce(old.urgent, false) and coalesce(new.urgent, false))
     ) then
    raise exception using errcode='22023', message='NEED_TERMINAL_IMMUTABLE';
  end if;

  if new.requester_account_id <> old.requester_account_id then
    raise exception using errcode='42501', message='NEED_OWNER_IMMUTABLE';
  end if;

  material :=
       new.task_country_code is distinct from old.task_country_code
    or new.task_timezone is distinct from old.task_timezone
    or
       new.title is distinct from old.title
    or new.description is distinct from old.description
    or new.category is distinct from old.category
    or new.required_slots is distinct from old.required_slots
    or new.mode is distinct from old.mode
    or new.requester_price_rsd is distinct from old.requester_price_rsd
    or new.required_skills is distinct from old.required_skills
    or new.required_tools is distinct from old.required_tools
    or new.required_vehicles is distinct from old.required_vehicles
    or new.required_licenses is distinct from old.required_licenses
    or new.minimum_experience_years is distinct from old.minimum_experience_years
    or new.verified_identity_required is distinct from old.verified_identity_required
    or new.schedule_kind is distinct from old.schedule_kind
    or new.starts_at is distinct from old.starts_at
    or new.ends_at is distinct from old.ends_at
    or new.execution_location_mode is distinct from old.execution_location_mode
    or new.approximate_lat is distinct from old.approximate_lat
    or new.approximate_lng is distinct from old.approximate_lng
    or new.approximate_city is distinct from old.approximate_city
    or new.approximate_area is distinct from old.approximate_area
    or new.public_photo_paths is distinct from old.public_photo_paths
    or new.response_deadline is distinct from old.response_deadline;

  if token = 'CONFIRM_EDIT' then
    if old.status not in ('DRAFT','PUBLISHED','SELECTION') or new.status <> 'DRAFT' then
      raise exception using errcode='22023', message='CONFIRMED_EDIT_STATUS_INVALID';
    end if;
    if new.revision <> old.revision + 1 then
      raise exception using errcode='22023', message='CONFIRMED_EDIT_REVISION_INVALID';
    end if;
    if exists (select 1 from public.agreements a where a.need_id = old.id)
       or exists (select 1 from public.need_selections s where s.need_id = old.id)
       or exists (select 1 from public.marketplace_responses r where r.need_id = old.id and r.status = 'SELECTED') then
      raise exception using errcode='P0001', message='NEED_EDIT_LOCKED_AFTER_FIRST_DOGOVOR';
    end if;
    if new.published_at is not null or new.response_deadline is not null then
      raise exception using errcode='22023', message='CONFIRMED_EDIT_PUBLICATION_METADATA_NOT_CLEARED';
    end if;
    if coalesce(new.urgent, false)
       or new.urgent_activated_at is not null
       or new.urgent_expires_at is not null
       or new.urgent_policy_version is not null then
      raise exception using errcode='22023', message='CONFIRMED_EDIT_URGENT_METADATA_NOT_CLEARED';
    end if;
    return new;
  end if;

  if new.status is distinct from old.status then
    if not (
         (token = 'PUBLISH' and old.status = 'DRAFT' and new.status = 'PUBLISHED')
      or (token = 'SELECT' and old.status in ('PUBLISHED','SELECTION') and new.status in ('SELECTION','ACTIVE'))
      or (token = 'CANCEL_NEED' and old.status in ('DRAFT','PUBLISHED','SELECTION') and new.status = 'CANCELLED')
      or (token = 'CANCEL_AGREEMENT' and old.status in ('ACTIVE','SELECTION') and new.status = 'SELECTION')
      or (token = 'EXPIRE' and old.status in ('PUBLISHED','SELECTION') and new.status = 'EXPIRED')
      or (token = 'COMPLETE' and old.status in ('ACTIVE','SELECTION') and new.status = 'COMPLETED')
    ) then
      raise exception using errcode='22023', message='NEED_STATUS_TRANSITION_REQUIRES_RPC';
    end if;
  end if;

  if token is null then
    if new.revision is distinct from old.revision then
      raise exception using errcode='42501', message='NEED_REVISION_IS_SERVER_OWNED';
    end if;
    if new.urgent is distinct from old.urgent then raise exception using errcode='42501', message='URGENT_IS_SERVER_OWNED'; end if;
    if new.urgent_activated_at is distinct from old.urgent_activated_at then raise exception using errcode='42501', message='URGENT_ACTIVATED_AT_IS_SERVER_OWNED'; end if;
    if new.urgent_expires_at is distinct from old.urgent_expires_at then raise exception using errcode='42501', message='URGENT_EXPIRES_AT_IS_SERVER_OWNED'; end if;
    if new.urgent_policy_version is distinct from old.urgent_policy_version then raise exception using errcode='42501', message='URGENT_POLICY_VERSION_IS_SERVER_OWNED'; end if;
    if new.published_at is distinct from old.published_at then raise exception using errcode='42501', message='PUBLISHED_AT_IS_SERVER_OWNED'; end if;
    if new.response_deadline is distinct from old.response_deadline then raise exception using errcode='42501', message='RESPONSE_DEADLINE_IS_SERVER_OWNED'; end if;
  end if;

  if material then
    if old.status in ('PUBLISHED','SELECTION') then
      raise exception using errcode='22023', message='PUBLIC_NEED_EDIT_REQUIRES_CONFIRM_COMMAND';
    elsif old.status <> 'DRAFT' then
      raise exception using errcode='P0001', message='NEED_NOT_EDITABLE';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.safety_guard_interaction_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a public.agreements; other uuid;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

 if tg_table_name='marketplace_responses' then
  if new.status not in('SUBMITTED','DELIVERED','VIEWED','SHORTLISTED','SELECTED') then return new; end if;
  select requester_account_id into other from public.needs where id=new.need_id;
  perform private.safety_assert_pair(new.worker_account_id,other);
 elsif tg_table_name='agreements' then
  perform private.safety_assert_pair(new.requester_account_id,new.worker_account_id);
 elsif tg_table_name='agreement_messages' then
  select * into a from public.agreements where id=new.agreement_id;
  perform private.safety_assert_pair(a.requester_account_id,a.worker_account_id);
 elsif tg_table_name='agreement_change_proposals' then
  if tg_op='UPDATE' and new.status<>'ACCEPTED' then return new; end if;
  select * into a from public.agreements where id=new.agreement_id;
  perform private.safety_assert_pair(a.requester_account_id,a.worker_account_id);
 elsif tg_table_name='access_grants' then
  if new.status<>'GRANTED' then return new; end if;
  perform private.safety_assert_pair(new.granted_by_account_id,new.granted_to_account_id);
 end if;
 return new;
end;
$function$

